 clanwall:{name:'أستظلّ بحماهم',kind:'اعتماد',clan:true,cost:1,block:10,end:true,text:'١٠ اتّقاء، ثم ينتهي دورك فورًا وينفذ الخصوم نياتهم. أمان يقيّد مبادرتك.',icon:'shield'},
