 hunger:{name:'أُميت الجوع',kind:'جَلَد',cost:1,damage:6,text:'٦ ضرر؛ تصبح ١٠ إذا كانت صحتك ١٦ أو أقل.',icon:'sun'},
 run:{name:'أسبق المطارد',kind:'عَدْو',cost:1,block:8,draw:1,text:'٨ اتّقاء واسحب بطاقة.',icon:'trail'},
 resolve:{name:'أجمع عزمي',kind:'عزم',cost:0,draw:2,hurt:2,text:'اخسر صحتين واسحب بطاقتين. الاتقاء لا يحجب هذه الكلفة.',icon:'sun'},
 wolf:{name:'ولي دونكم أهلون',kind:'رفقة',cost:1,damage:7,block:4,text:'٧ ضرر و٤ اتّقاء. تحتاج رفقة الذئب.',icon:'wolf'},
 riposte:{name:'حدّ الصبر',kind:'إتمام جَلَد',cost:2,damage:10,finish:'جلد',combo:6,text:'١٠ ضرر، أو ١٦ بعد تمهيد جَلَد مباشرة. مقاطعة التسلسل تُفقدك الإتمام.',icon:'blade'},
 opening:{name:'أصيب الغرّة',kind:'إتمام حيلة',cost:1,damage:6,finish:'حيلة',combo:5,text:'٦ ضرر، أو ١١ بعد تمهيد حيلة مباشرة. مقاطعة التسلسل تُفقدك الإتمام.',icon:'arrow'},
 study:{name:'أقرأ الطريق',kind:'حيلة',cost:1,weak:5,draw:1,setup:'حيلة',text:'اخفض هجوم خصم ٥ واسحب بطاقة. تمهيد حيلة.',icon:'trail'},
 steady:{name:'أثبت على المشقّة',kind:'جَلَد',cost:1,block:5,draw:1,setup:'جلد',text:'٥ اتّقاء واسحب بطاقة. تمهيد جَلَد.',icon:'shield'},
 offering:{name:'أفسح النصيب',kind:'تعفّف',cost:1,block:4,bank:1,exhaust:true,text:'٤ اتّقاء، وطاقة إضافية في الدور القادم. تُستنفد لبقية المواجهة.',icon:'sun'},
